public class Main {
    public static void main(String[] args) {
        Set<Point> points = new HashSet<>(List.of(new Point(1, 2), new Point(3, 4), new Point(1, 2)));
        System.out.println("set of 3 points with one duplicate: " + points.size());
    }
}

